var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    try {
      ms(null);
    } catch (err) {
      assert.strictEqual(err.message, 'null');
    }
    try {
      ms(undefined);
    } catch (err) {
      assert.strictEqual(err.message, 'undefined');
    }
    try {
      ms('');
    } catch (err) {
      assert.strictEqual(err.message, '""');
    }
    try {
      ms('invalid');
    } catch (err) {
      assert.strictEqual(err.message, '"invalid"');
    }
    try {
      ms(NaN);
    } catch (err) {
      assert.strictEqual(err.message, 'NaN');
    }
    try {
      ms(Infinity);
    } catch (err) {
      assert.strictEqual(err.message, 'Infinity');
    }
  });
});

